-- Keep the cursor where it is when focus changes from the keyboard, gestures or rofi.
-- By default Hyprland warps it to the centre of the newly focused window.
hl.config({
    cursor = {
        no_warps = true,
    },
})

-- Let a client draw its next frame while the last one is still being shown. Without it
-- Quickshell's overview / gesture got a frame callback only every other refresh: ~72 fps
-- on the 144 Hz panel even though rendering took ~1 ms (measured with
-- QT_LOGGING_RULES=qt.scenegraph.time.renderloop=true). With it: mostly 7-8 ms frames.
hl.config({
    render = {
        new_render_scheduling = true,
    },
})

hl.config({
    input = {
        kb_layout  = "us",
        kb_variant = "",
        kb_model   = "",
        kb_options = "",
        kb_rules   = "",

        -- Click to focus (Windows/macOS style). Hovering does not steal focus; scrolling
        -- still goes to the window under the cursor.
        follow_mouse = 2,
        -- Default 1 moves focus to the window under the cursor whenever focus goes between a
        -- tiled and a floating window, which undoes 3-finger window cycling. Keep focus where
        -- the cycle / click put it.
        float_switch_override_focus = 0,

        -- Pointer speed, acceleration and the scroll factors below are only defaults: the
        -- Settings window (Quickshell, config/settings.json) pushes its own values over them
        -- at start and after every reload.
        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.

        -- Scroll speed for every app (mouse wheel / touchpad). Higher = faster. Inertia is not
        -- done here (Wayland leaves it to apps): see kitty.conf, VS Code settings and
        -- extras/firefox/user.js.
        scroll_factor = 1.0,

        touchpad = {
            scroll_factor        = 0.5,   -- 1.0 scrolled too far per swipe on the TUF's pad
            natural_scroll       = true,  -- macOS-style scrolling
            tap_to_click         = true,
            clickfinger_behavior = true,  -- two-finger click = right click
            disable_while_typing = true,
        },
    },
})

