hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Keep title bars reachable. A floating window dragged so its hyprbars title bar ends up
-- under the top bar or off the screen edge can no longer be grabbed, so push it back: title
-- bar fully below the reserved top area, at least `keep` px of it left on screen
-- horizontally and at the bottom.
-- A maximized window (tag `maximized`, scripts/toggle-maximize.sh) has no title bar and
-- fills the work area; once it is moved or resized away from that it gets the tag (and
-- so its title bar) back, and the check applies again.
local function has_tag(w, tag)
    for _, t in ipairs(type(w.tags) == "table" and w.tags or {}) do
        if t:gsub("%*$", "") == tag then return true end
    end
    return false
end
local function keep_on_screen(w)
    if not w or not w.floating or (w.fullscreen or 0) ~= 0 or not w.monitor then return end
    local m = w.monitor
    local bar, border, keep = 20, 1, 120          -- hyprbars bar_height, window border
    local mx, my = m.position.x, m.position.y
    local mw, mh = m.width / m.scale, m.height / m.scale
    local r = m.reserved
    local x, y = w.at.x, w.at.y
    if has_tag(w, "maximized") then
        local function near(a, b) return math.abs(a - b) <= 2 end
        local fits = near(x, mx + r.left) and near(y, my + r.top)
            and near(w.size.x, mw - r.left - r.right) and near(w.size.y, mh - r.top - r.bottom)
        if fits then return end
        hl.dispatch(hl.dsp.window.tag({ tag = "-maximized", window = "address:" .. w.address }))
        hl.exec_cmd("qs ipc call windows refresh")
    end
    local nx = math.min(math.max(x, mx + r.left - w.size.x + keep), mx + mw - r.right - keep)
    local ny = math.min(math.max(y, my + r.top + bar + border), my + mh - r.bottom - keep)
    if nx ~= x or ny ~= y then
        hl.dispatch(hl.dsp.window.move({ x = math.floor(nx), y = math.floor(ny), window = "address:" .. w.address }))
    end
end
-- Checked on a short timer rather than on mouse release: a `release` bind on mouse:272
-- swallows the release even with non_consuming, so apps think the button is still held.
-- The window is only pushed back once the drag is over (left button up and the position
-- unchanged for two ticks), so it slides back like the maximize/restore animation.
local last_pos, still = "", 0
hl.timer(function()
    local w = hl.get_active_window()
    if not w then return end
    local pos = w.address .. ":" .. w.at.x .. "," .. w.at.y
    still = (pos == last_pos) and still + 1 or 0
    last_pos = pos
    local ok, held = pcall(hl.is_key_down, 272)   -- BTN_LEFT
    if still >= 2 and not (ok and held) then keep_on_screen(w) end
end, { timeout = 150, type = "repeat" })
-- Rescue a window that is already out of reach (or just tidy up): centre it
hl.bind(mainMod .. " + C", hl.dsp.window.center())

-- Laptop multimedia keys for volume and LCD brightness. The Quickshell OSD notices volume
-- changes by itself; brightness has to tell it (sysfs can't be watched).
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+ && qs ipc call osd brightness"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%- && qs ipc call osd brightness"),                  { locked = true, repeating = true })

-- Suspend hangs on the TUF, so logind leaves the power key and the lid alone
-- (hosts/tuf-f16/etc/systemd/logind.conf.d): a short press of the power button turns the
-- screen back on, closing the lid locks (logind) and turns the screen off.
local dpms_on  = hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.dpms({ action = \"on\" })'")
local dpms_off = hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.dpms({ action = \"off\" })'")
hl.bind("XF86PowerOff",         dpms_on,  { locked = true })
hl.bind("switch:on:Lid Switch",  dpms_off, { locked = true })
hl.bind("switch:off:Lid Switch", dpms_on,  { locked = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

-- Mac-style: windows float and open centered by default
hl.window_rule({
    name  = "float-by-default",
    match = { class = ".*" },

    float  = true,
    center = true,
})

-- Maximized windows (tag set by scripts/toggle-maximize.sh) lose their title bar, border
-- and rounding; the Quickshell top bar shows their title and buttons instead
hl.window_rule({
    name  = "maximized-bare",
    match = { tag = "maximized" },

    ["hyprbars:no_bar"] = true,
    border_size = 0,
    rounding    = 0,
})

-- New windows open at 70% of the screen (centred by the rule above) instead of whatever
-- small size the app asks for, so there is something to see at once. Left alone: modal
-- dialogs (save / open...), picture-in-picture and small utility windows that size
-- themselves (Quickshell's Settings, mixers, network / Bluetooth managers, polkit).
hl.window_rule({
    name  = "open-large",
    match = {
        modal = false,
        class = "negative:^(org\\.quickshell|hyprland-run|hyprpolkitagent|org\\.pulseaudio\\.pavucontrol|nm-connection-editor|blueman-manager|xdg-desktop-portal.*)$",
        title = "negative:^(Picture.in.[Pp]icture)$",
    },

    size = "monitor_w*0.7 monitor_h*0.7",
})

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Quickshell animates these itself: the window overview (a layer fade would make the
-- windows under it look like they fade out while their thumbnails fly to the grid) and
-- the bar's drop-down panels (they grow out of their button and back)
hl.layer_rule({
    name    = "overview-no-anim",
    match   = { namespace = "^quickshell-(overview|popup|launcher)$" },
    no_anim = true,
})

-- The app launcher's backdrop is translucent: blur what is behind it
hl.layer_rule({
    name         = "launcher-blur",
    match        = { namespace = "^quickshell-launcher$" },
    blur         = true,
    ignore_alpha = 0.1,
})

-- Layer rules also return a handle.
